// Trouver l'erreur : Maths Sup, cinquante raisonnements classés par thème (MEMO_atlas_activites.md §145 et §147).
import { T, faux } from './raisonner-outils.js';
const H = ` Si la ligne est fausse, c'est qu'une erreur a été commise plus haut.`;
const F = 'fondements', A = 'algebre', L = 'lineaire', N = 'analyse', Pr = 'probabilites';
export default [
// ---------- Fondements ----------
faux('quantificateurs', 'sup', F, 'ma-01', 'Un réel plus grand que lui-même', T`« Démontrons » qu'il existe un réel strictement plus grand que lui-même.`, [
  [T`Pour tout réel $x$, il existe un réel $y$ tel que $y > x$ : par exemple $y = x + 1$.`, T`C'est exact : $x + 1 > x$ pour tout réel $x$. En symboles, $\forall x \in \mathbb{R},\ \exists y \in \mathbb{R},\ y > x$.`],
  [T`Autrement dit, il existe un réel $y$ tel que, pour tout réel $x$, on ait $y > x$.`],
  [T`Cette inégalité vaut pour tout réel $x$, en particulier pour $x = y$ : donc $y > y$.`, T`Une propriété vraie pour tout réel $x$ l'est pour chaque réel particulier, y compris $y$ : le passage est correct.` + H] ],
  T`On a échangé les deux quantificateurs, et ce n'est pas « autrement dit ». Dans $\forall x,\ \exists y$, le réel $y$ est choisi après $x$ et dépend de lui : c'est $x + 1$. Dans $\exists y,\ \forall x$, un même $y$ doit convenir à tous les $x$ à la fois : ce serait un réel plus grand que tous les réels, qui n'existe pas.`,
  T`On peut échanger deux quantificateurs de même nature, jamais un $\forall$ et un $\exists$. L'implication $\exists y\,\forall x \Rightarrow \forall x\,\exists y$ est vraie ; sa réciproque est fausse en général.`, T`Dans la ligne 1, le réel $y$ dépend-il de $x$ ?`),
faux('reciproque', 'sup', F, 'ma-01', 'La réciproque à la place de l\'implication', T`« Démontrons » que tout entier dont le carré est un multiple de 4 est lui-même un multiple de 4.`, [
  [T`Soit $n$ un entier multiple de 4 : il existe un entier $k$ tel que $n = 4k$.`, T`C'est la définition d'un multiple de 4 : poser une hypothèse n'est pas une erreur.`],
  [T`Alors $n^2 = 16k^2 = 4 \times (4k^2)$ : le carré de $n$ est un multiple de 4.`, T`Le calcul est exact, et $4k^2$ est un entier.`],
  [T`On a donc établi : si $n$ est un multiple de 4, alors $n^2$ est un multiple de 4.`, T`C'est exactement ce que démontrent les deux premières lignes.`],
  [T`Par conséquent, si $n^2$ est un multiple de 4, alors $n$ est un multiple de 4.`] ],
  T`On a démontré l'implication $A \Rightarrow B$ et conclu $B \Rightarrow A$ : c'est la réciproque, qui est un autre énoncé, et qui est fausse ici. Pour $n = 2$, le carré $4$ est un multiple de 4 et $n$ n'en est pas un. Ce qui équivaut à $A \Rightarrow B$, c'est sa contraposée : si $n^2$ n'est pas un multiple de 4, alors $n$ n'est pas un multiple de 4.`,
  T`$A \Rightarrow B$ équivaut à sa contraposée $(\text{non } B) \Rightarrow (\text{non } A)$, pas à sa réciproque $B \Rightarrow A$. Avant de rédiger, on écrit ce que l'on suppose et ce que l'on veut obtenir.`, T`Essayez l'énoncé avec $n = 2$.`),
faux('image-intersection', 'sup', F, 'ma-02', 'L\'image d\'une intersection', T`Soit $f : \mathbb{R} \to \mathbb{R}$, $x \mapsto x^2$, $A = [-1, 0]$ et $B = [0, 1]$. « Démontrons » que $1 = 0$.`, [
  [T`On a $f(A) = [0, 1]$ et $f(B) = [0, 1]$.`, T`C'est exact : le carré d'un réel de $[-1, 0]$ ou de $[0, 1]$ décrit $[0, 1]$.`],
  [T`On a $A \cap B = \{0\}$, donc $f(A \cap B) = \{0\}$.`, T`C'est exact : 0 est le seul réel commun aux deux segments, et $f(0) = 0$.`],
  [T`L'image d'une intersection est l'intersection des images : $f(A \cap B) = f(A) \cap f(B)$.`],
  [T`Donc $\{0\} = [0, 1]$. En particulier, 1 appartient à $\{0\}$ : $1 = 0$.`, T`On a remplacé chaque membre par sa valeur, calculée plus haut : le passage est correct.` + H] ],
  T`Seule l'inclusion $f(A \cap B) \subset f(A) \cap f(B)$ est vraie en général. L'autre demande que $f$ soit injective : un élément de $f(A) \cap f(B)$ s'écrit $f(a) = f(b)$ avec $a \in A$ et $b \in B$, et rien ne dit que $a = b$. Ici $1 = f(-1) = f(1)$, avec $-1 \in A$ et $1 \in B$. Pour la réunion, en revanche, l'égalité $f(A \cup B) = f(A) \cup f(B)$ est toujours vraie.`,
  T`L'image directe se comporte bien avec la réunion, mal avec l'intersection. L'image <em>réciproque</em>, elle, respecte toutes les opérations ensemblistes.`, T`La fonction $f$ est-elle injective ?`),
faux('reflexive', 'sup', F, 'ma-02', 'Symétrique et transitive, donc réflexive ?', T`« Démontrons » que toute relation $\sim$ symétrique et transitive sur un ensemble $E$ est réflexive.`, [
  [T`Soit $x$ un élément de $E$, et soit $y$ un élément de $E$ tel que $x \sim y$.`],
  [T`Par symétrie, $y \sim x$.`, T`C'est la définition de la symétrie, appliquée à $x \sim y$ : le passage est correct.` + H],
  [T`On a $x \sim y$ et $y \sim x$ : par transitivité, $x \sim x$.`, T`C'est la définition de la transitivité, où le troisième élément est $x$ lui-même : le passage est correct.` + H],
  [T`Ceci vaut pour tout $x$ de $E$ : la relation est réflexive.`, T`Si l'on a obtenu $x \sim x$ pour un $x$ quelconque, la conclusion est légitime : le passage est correct.` + H] ],
  T`Rien ne garantit qu'un tel $y$ existe : un élément peut n'être en relation avec personne. Sur $\mathbb{Z}$, la relation « $xy > 0$ » est symétrique et transitive, mais 0 n'est en relation avec aucun entier, pas même avec lui-même. Le raisonnement montre seulement que tout élément en relation avec au moins un autre est en relation avec lui-même.`,
  T`« Soit $y$ tel que… » suppose qu'un tel $y$ existe. La réflexivité est bien une troisième condition, indépendante des deux autres.`, T`Chaque objet introduit par « soit » existe-t-il à coup sûr ?`),
// ---------- Algèbre ----------
faux('pgcd-ppcm-trois', 'sup', A, 'ma-12', '4 = 8', T`« Démontrons » que $4 = 8$.`, [
  [T`Pour deux entiers strictement positifs $a$ et $b$, on a $\operatorname{pgcd}(a, b) \times \operatorname{ppcm}(a, b) = ab$.`, T`C'est un résultat du cours, valable pour deux entiers.`],
  [T`Cette formule s'étend à trois entiers : $\operatorname{pgcd}(a, b, c) \times \operatorname{ppcm}(a, b, c) = abc$.`],
  [T`Pour $a = b = c = 2$, le PGCD vaut 2 et le PPCM vaut 2.`, T`C'est exact : 2 est à la fois le plus grand diviseur commun et le plus petit multiple commun.`],
  [T`Donc $2 \times 2 = 2 \times 2 \times 2$, c'est-à-dire $4 = 8$.`, T`On a reporté ces valeurs dans la formule écrite plus haut : le passage est correct.` + H] ],
  T`La formule ne s'étend pas à trois entiers. Pour chaque nombre premier $p$, elle exprime que le plus petit et le plus grand de deux exposants ont pour somme la somme des deux exposants ; avec trois exposants, le minimum et le maximum laissent de côté celui du milieu.`,
  T`$\operatorname{pgcd}(a, b) \times \operatorname{ppcm}(a, b) = ab$ est propre à deux entiers. Avant de généraliser une formule, on la teste sur le cas le plus simple.`, T`D'où vient la formule pour deux entiers, en termes de décomposition en facteurs premiers ?`),
faux('degre-somme', 'sup', A, 'ma-13', '0 = 1 avec des degrés', T`Soit $P = X + 1$ et $Q = -X$. « Démontrons » que $0 = 1$.`, [
  [T`Les polynômes $P$ et $Q$ sont tous deux de degré 1.`, T`C'est exact : leurs coefficients dominants, 1 et $-1$, ne sont pas nuls.`],
  [T`Le degré d'une somme est le plus grand des deux degrés : $\deg(P + Q) = 1$.`],
  [T`Or $P + Q = 1$, polynôme constant non nul, de degré 0.`, T`Le calcul de la somme est exact, et une constante non nulle est de degré 0.`],
  [T`Donc $0 = 1$.`, T`Le degré d'un polynôme est unique : deux valeurs du même degré sont égales. Le passage est correct.` + H] ],
  T`On a seulement $\deg(P + Q) \leqslant \max(\deg P, \deg Q)$. Il y a égalité quand les degrés sont différents, mais quand ils sont égaux, les termes dominants peuvent se détruire, comme ici $X$ et $-X$. Pour le produit, en revanche, la formule $\deg(PQ) = \deg P + \deg Q$ est une égalité.`,
  T`$\deg(P + Q) \leqslant \max(\deg P, \deg Q)$, avec égalité si $\deg P \neq \deg Q$.`, T`Que deviennent les termes de plus haut degré dans la somme ?`),
faux('sans-racine', 'sup', A, 'ma-13', 'Sans racine, donc irréductible ?', T`« Démontrons » que le polynôme $X^4 + 1$ est irréductible dans $\mathbb{R}[X]$.`, [
  [T`Pour tout réel $x$, on a $x^4 + 1 \geqslant 1 > 0$ : le polynôme $X^4 + 1$ n'a aucune racine réelle.`, T`C'est exact : une puissance quatrième est positive.`],
  [T`Il n'est donc divisible par aucun polynôme réel de degré 1.`, T`C'est exact : un polynôme est divisible par $X - a$ si et seulement si $a$ en est racine.`],
  [T`Un polynôme qui n'a aucun diviseur de degré 1 est irréductible : $X^4 + 1$ est irréductible dans $\mathbb{R}[X]$.`] ],
  T`Un polynôme de degré 4 peut se factoriser en deux polynômes de degré 2 sans avoir de diviseur de degré 1. C'est le cas ici : $X^4 + 1 = (X^2 + 1)^2 - 2X^2 = \bigl(X^2 + \sqrt2\,X + 1\bigr)\bigl(X^2 - \sqrt2\,X + 1\bigr)$. Le critère « sans racine, donc irréductible » ne vaut que pour les degrés 2 et 3. Dans $\mathbb{R}[X]$, les irréductibles sont les polynômes de degré 1 et ceux de degré 2 à discriminant strictement négatif.`,
  T`« Irréductible » et « sans racine » ne coïncident qu'en degrés 2 et 3. Aucun polynôme réel de degré supérieur ou égal à 3 n'est irréductible dans $\mathbb{R}[X]$.`, T`Écrivez $X^4 + 1$ comme une différence de deux carrés.`),
faux('fermat-reciproque', 'sup', A, 'ma-12', '341 serait premier', T`« Démontrons » que 341 est un nombre premier.`, [
  [T`On a $2^{10} = 1024 = 3 \times 341 + 1$ : donc $2^{10} \equiv 1 \pmod{341}$.`, T`Le calcul est exact : $3 \times 341 = 1023$.`],
  [T`En élevant à la puissance 34 : $2^{340} \equiv 1 \pmod{341}$.`, T`Les congruences sont compatibles avec les puissances, et $1^{34} = 1$.`],
  [T`D'après le petit théorème de Fermat, si $p$ est premier et ne divise pas $a$, alors $a^{p-1} \equiv 1 \pmod p$.`, T`C'est l'énoncé exact du théorème.`],
  [T`L'entier 341 vérifie cette congruence pour $a = 2$ : il est donc premier.`] ],
  T`On a utilisé la réciproque du petit théorème de Fermat, qui est fausse : la congruence est nécessaire pour être premier, pas suffisante. En fait $341 = 11 \times 31$. Les entiers composés qui passent ainsi le test pour $a = 2$ sont appelés pseudo-premiers de base 2, et 341 est le plus petit d'entre eux.`,
  T`Le test de Fermat peut prouver qu'un entier est composé, quand la congruence échoue, jamais qu'il est premier.`, T`Cherchez un diviseur de 341 parmi les petits nombres premiers.`),
faux('exp-complexe', 'sup', A, 'ma-04', '2π = 0', T`« Démontrons » que $2\pi = 0$.`, [
  [T`On a $e^{2i\pi} = \cos(2\pi) + i\sin(2\pi) = 1$.`, T`C'est exact.`],
  [T`On a aussi $e^{0} = 1$.`, T`C'est exact.`],
  [T`Donc $e^{2i\pi} = e^{0}$. L'exponentielle ne prenant jamais deux fois la même valeur, $2i\pi = 0$.`],
  [T`En divisant par $2i$, puis en multipliant par 2 : $2\pi = 0$.`, T`Le nombre $i$ n'est pas nul, les opérations sont permises : le passage est correct.` + H] ],
  T`L'exponentielle est injective sur $\mathbb{R}$, où elle est strictement croissante, mais pas sur $\mathbb{C}$ : elle est périodique de période $2i\pi$. L'égalité $e^z = e^{z'}$ équivaut à $z - z' \in 2i\pi\mathbb{Z}$, ce qui est bien le cas ici.`,
  T`$e^{z} = e^{z'}$ si et seulement si $z = z' + 2ik\pi$ avec $k \in \mathbb{Z}$. C'est pour cela qu'un argument n'est défini qu'à $2\pi$ près, et qu'il n'y a pas de logarithme sur $\mathbb{C}^*$ tout entier.`, T`L'exponentielle complexe est-elle injective ?`),
faux('somme-triangulaire', 'sup', A, 'ma-03', '5 = 4 avec une somme double', T`On pose $S = \displaystyle\sum_{i=1}^{2}\,\sum_{j=1}^{i} i$. « Démontrons » que $5 = 4$.`, [
  [T`Calcul direct : pour $i = 1$, la somme intérieure a un terme, égal à 1 ; pour $i = 2$, elle a deux termes, égaux à 2. Donc $S = 1 + 2 + 2 = 5$.`, T`Le calcul est exact : l'indice $j$ ne sert qu'à compter les termes.`],
  [T`Les sommes étant finies, on peut les intervertir : $S = \displaystyle\sum_{j=1}^{2}\,\sum_{i=1}^{j} i$.`],
  [T`Pour $j = 1$, la somme intérieure vaut 1 ; pour $j = 2$, elle vaut $1 + 2 = 3$. Donc $S = 4$.`, T`La somme écrite plus haut est bien calculée : le passage est correct.` + H],
  [T`Donc $5 = 4$.`, T`Deux valeurs d'un même nombre sont égales : le passage est correct.` + H] ],
  T`On n'intervertit pas les symboles en gardant chacun ses bornes quand les bornes de l'un dépendent de l'indice de l'autre. Le domaine de sommation est le triangle $1 \leqslant j \leqslant i \leqslant 2$ : à $j$ fixé, c'est $i$ qui varie de $j$ à 2. La bonne interversion est $S = \displaystyle\sum_{j=1}^{2}\,\sum_{i=j}^{2} i = (1 + 2) + 2 = 5$.`,
  T`$\displaystyle\sum_{i=1}^{n}\sum_{j=1}^{i} a_{ij} = \sum_{j=1}^{n}\sum_{i=j}^{n} a_{ij}$. Pour une somme triangulaire, on écrit d'abord le domaine sous la forme $1 \leqslant j \leqslant i \leqslant n$.`, T`Quels sont les couples $(i, j)$ sur lesquels on somme ?`),
// ---------- Algèbre linéaire ----------
faux('inverse-produit', 'sup', L, 'ma-16', 'L\'inverse d\'un produit', T`Soit $A = \begin{pmatrix} 1 & 1 \\ 0 & 1 \end{pmatrix}$ et $B = \begin{pmatrix} 1 & 0 \\ 1 & 1 \end{pmatrix}$. « Démontrons » que $3 = 1$.`, [
  [T`Les matrices $A$ et $B$ sont inversibles : $A^{-1} = \begin{pmatrix} 1 & -1 \\ 0 & 1 \end{pmatrix}$ et $B^{-1} = \begin{pmatrix} 1 & 0 \\ -1 & 1 \end{pmatrix}$.`, T`On le vérifie en calculant $AA^{-1}$ et $BB^{-1}$, qui valent tous deux $I_2$.`],
  [T`On a $AB = \begin{pmatrix} 2 & 1 \\ 1 & 1 \end{pmatrix}$.`, T`Le produit est bien calculé.`],
  [T`L'inverse d'un produit est le produit des inverses : $(AB)^{-1} = A^{-1}B^{-1} = \begin{pmatrix} 2 & -1 \\ -1 & 1 \end{pmatrix}$.`],
  [T`Donc $\begin{pmatrix} 2 & 1 \\ 1 & 1 \end{pmatrix}\begin{pmatrix} 2 & -1 \\ -1 & 1 \end{pmatrix} = I_2$. Or ce produit vaut $\begin{pmatrix} 3 & -1 \\ 1 & 0 \end{pmatrix}$ : en haut à gauche, $3 = 1$.`, T`Le produit d'une matrice par son inverse est $I_2$, et le produit écrit est bien calculé : le passage est correct.` + H] ],
  T`L'inverse d'un produit est le produit des inverses <em>dans l'ordre contraire</em> : $(AB)^{-1} = B^{-1}A^{-1}$, puisque $AB\,B^{-1}A^{-1} = A\,I_2\,A^{-1} = I_2$. Ici $B^{-1}A^{-1} = \begin{pmatrix} 1 & -1 \\ -1 & 2 \end{pmatrix}$, et l'on vérifie que c'est bien l'inverse de $AB$. La matrice $A^{-1}B^{-1}$, elle, est l'inverse de $BA$.`,
  T`$(AB)^{-1} = B^{-1}A^{-1}$, comme $(AB)^{\top} = B^{\top}A^{\top}$ : on enlève en dernier ce que l'on a mis en premier.`, T`Calculez le produit $AB \times B^{-1}A^{-1}$ sans coefficients, en regroupant les matrices.`),
faux('deux-a-deux', 'sup', L, 'ma-14', 'Trois vecteurs libres dans le plan', T`« Démontrons » que $\mathbb{R}^2$ contient une famille libre de trois vecteurs, donc que $3 \leqslant 2$.`, [
  [T`Soit $u = (1, 0)$, $v = (0, 1)$ et $w = (1, 1)$. Ces vecteurs sont deux à deux non colinéaires.`, T`C'est exact : aucun des trois n'est multiple d'un autre.`],
  [T`Des vecteurs deux à deux non colinéaires forment une famille libre : $(u, v, w)$ est libre.`],
  [T`Or, dans un espace de dimension $n$, une famille libre a au plus $n$ vecteurs, et $\mathbb{R}^2$ est de dimension 2 : donc $3 \leqslant 2$.`, T`C'est un théorème du cours sur la dimension : le passage est correct.` + H] ],
  T`La liberté n'est pas une propriété « deux à deux » : il faut qu'aucun vecteur ne soit combinaison linéaire de <em>tous</em> les autres. Ici $w = u + v$ : la famille est liée. « Deux à deux non colinéaires » n'équivaut à « libre » que pour une famille de deux vecteurs.`,
  T`Une famille est libre si la seule combinaison linéaire nulle est celle dont tous les coefficients sont nuls. On ne teste pas la liberté par paires.`, T`Cherchez une relation entre $u$, $v$ et $w$.`),
faux('somme-reunion', 'sup', L, 'ma-14', 'Somme ou réunion ?', T`Dans $\mathbb{R}^2$, soit $F$ la droite engendrée par $(1, 0)$ et $G$ la droite engendrée par $(0, 1)$. « Démontrons » que $1 = 0$.`, [
  [T`Les sous-espaces $F$ et $G$ sont supplémentaires : $\mathbb{R}^2 = F \oplus G$.`, T`C'est exact : tout vecteur $(x, y)$ s'écrit de façon unique $(x, 0) + (0, y)$.`],
  [T`Tout vecteur de $\mathbb{R}^2$ appartient donc à $F$ ou à $G$.`],
  [T`En particulier, le vecteur $(1, 1)$ appartient à $F$ ou à $G$ : l'une de ses coordonnées est nulle, et $1 = 0$.`, T`Les vecteurs de $F$ ont une ordonnée nulle et ceux de $G$ une abscisse nulle : le passage est correct.` + H] ],
  T`On a confondu la somme $F + G$ avec la réunion $F \cup G$. Un vecteur de $F + G$ est la <em>somme</em> d'un vecteur de $F$ et d'un vecteur de $G$ ; il n'est en général dans aucun des deux. La réunion de deux droites distinctes n'est d'ailleurs pas un sous-espace vectoriel : elle n'est pas stable par addition.`,
  T`$F \oplus G = E$ signifie que tout vecteur se décompose de façon unique en $f + g$, pas que tout vecteur est dans $F$ ou dans $G$. Le supplémentaire n'est pas le complémentaire.`, T`Où se trouve le vecteur $(1, 1)$ par rapport aux deux axes ?`),
faux('dimension-somme', 'sup', L, 'ma-15', 'Un sous-espace de dimension 4 dans l\'espace', T`Dans $\mathbb{R}^3$, soit $F$ le plan d'équation $z = 0$ et $G$ le plan d'équation $x = 0$. « Démontrons » que $4 \leqslant 3$.`, [
  [T`Les sous-espaces $F$ et $G$ sont de dimension 2.`, T`C'est exact : ce sont deux plans vectoriels.`],
  [T`La dimension d'une somme est la somme des dimensions : $\dim(F + G) = 2 + 2 = 4$.`],
  [T`Or $F + G$ est un sous-espace de $\mathbb{R}^3$ : sa dimension est au plus 3.`, T`C'est exact : la dimension d'un sous-espace ne dépasse pas celle de l'espace.`],
  [T`Donc $4 \leqslant 3$.`, T`On a comparé les deux informations obtenues sur $\dim(F + G)$ : le passage est correct.` + H] ],
  T`La formule de Grassmann est $\dim(F + G) = \dim F + \dim G - \dim(F \cap G)$ : on retranche la dimension de l'intersection, comptée deux fois. Ici $F \cap G$ est la droite engendrée par $(0, 1, 0)$, et $\dim(F + G) = 2 + 2 - 1 = 3$. La formule sans correction ne vaut que si la somme est directe.`,
  T`$\dim(F + G) = \dim F + \dim G - \dim(F \cap G)$, à rapprocher de $\operatorname{Card}(A \cup B) = \operatorname{Card} A + \operatorname{Card} B - \operatorname{Card}(A \cap B)$.`, T`Quelle est l'intersection des deux plans ?`),
faux('det-lineaire', 'sup', L, 'ma-17', '4 = 2 avec un déterminant', T`« Démontrons » que $4 = 2$.`, [
  [T`On a $\det(I_2) = 1$.`, T`C'est exact.`],
  [T`La matrice $2I_2$ est diagonale, de coefficients diagonaux 2 et 2 : son déterminant est $2 \times 2 = 4$.`, T`C'est exact : le déterminant d'une matrice diagonale est le produit de ses coefficients diagonaux.`],
  [T`Le déterminant est linéaire : $\det(2I_2) = 2\det(I_2) = 2$.`],
  [T`Donc $4 = 2$.`, T`Deux valeurs du même déterminant sont égales : le passage est correct.` + H] ],
  T`Le déterminant n'est pas une application linéaire de la matrice : il est linéaire par rapport à <em>chaque colonne</em> séparément. Multiplier la matrice par $\lambda$ multiplie chacune des $n$ colonnes par $\lambda$, donc le déterminant par $\lambda^n$ : $\det(\lambda A) = \lambda^n \det A$. De même, $\det(A + B)$ n'est pas $\det A + \det B$.`,
  T`$\det(\lambda A) = \lambda^n \det(A)$ pour une matrice carrée de taille $n$. Le déterminant est multiplicatif, $\det(AB) = \det A \det B$, pas additif.`, T`Combien de colonnes ont été multipliées par 2 ?`),
faux('noyau-image', 'sup', L, 'ma-15', 'Noyau et image supplémentaires ?', T`Soit $u$ l'endomorphisme de $\mathbb{R}^2$ défini par $u(x, y) = (y, 0)$. « Démontrons » que $1 = 0$.`, [
  [T`Le noyau de $u$ est la droite engendrée par $(1, 0)$, et son image est aussi la droite engendrée par $(1, 0)$.`, T`C'est exact : $u(x, y) = (0, 0)$ équivaut à $y = 0$, et les vecteurs $(y, 0)$ décrivent la même droite.`],
  [T`D'après le théorème du rang, $\dim \operatorname{Ker} u + \dim \operatorname{Im} u = 1 + 1 = 2 = \dim \mathbb{R}^2$.`, T`C'est le théorème du rang, et il est bien vérifié ici.`],
  [T`Deux sous-espaces dont les dimensions ont pour somme celle de l'espace sont supplémentaires : $\mathbb{R}^2 = \operatorname{Ker} u \oplus \operatorname{Im} u$.`],
  [T`Leur intersection est donc réduite au vecteur nul. Or $(1, 0)$ appartient aux deux : $(1, 0) = (0, 0)$, et $1 = 0$.`, T`Deux sous-espaces supplémentaires ont une intersection nulle : le passage est correct.` + H] ],
  T`La condition sur les dimensions ne suffit pas : il faut en plus que l'intersection soit nulle, ou que la somme soit l'espace entier. Le théorème du rang relie des <em>dimensions</em> ; il ne dit pas que le noyau et l'image sont supplémentaires, et ils peuvent même être égaux, comme ici où $u \circ u = 0$.`,
  T`$F$ et $G$ sont supplémentaires dans $E$ de dimension finie si $\dim F + \dim G = \dim E$ <em>et</em> $F \cap G = \{0_E\}$. Le théorème du rang ne donne que la première condition.`, T`Comparez le noyau et l'image.`),
faux('surjectif-injectif', 'sup', L, 'ma-15', 'Surjectif, donc injectif ?', T`Soit $D$ l'endomorphisme de $\mathbb{R}[X]$ qui à un polynôme $P$ associe son polynôme dérivé $P'$. « Démontrons » que $1 = 0$.`, [
  [T`L'application $D$ est linéaire et surjective : tout polynôme est le dérivé d'un polynôme.`, T`C'est exact : $X^k$ est le dérivé de $\dfrac{X^{k+1}}{k+1}$, et l'on conclut par linéarité.`],
  [T`Un endomorphisme surjectif est injectif : $D$ est injective.`],
  [T`Son noyau est donc réduit au polynôme nul.`, T`Une application linéaire est injective si et seulement si son noyau est nul : le passage est correct.` + H],
  [T`Or $D(1) = 0$ : le polynôme constant 1 est dans le noyau. C'est donc le polynôme nul, et $1 = 0$.`, T`Le dérivé d'une constante est bien nul, et l'on applique la ligne précédente : le passage est correct.` + H] ],
  T`L'équivalence « injectif si et seulement si surjectif » vaut pour un endomorphisme d'un espace de dimension <em>finie</em> : c'est une conséquence du théorème du rang. L'espace $\mathbb{R}[X]$ est de dimension infinie, et la dérivation y est surjective sans être injective. À l'inverse, $P \mapsto XP$ y est injective sans être surjective.`,
  T`En dimension finie, un endomorphisme injectif ou surjectif est bijectif. En dimension infinie, les deux notions sont indépendantes.`, T`Quelle est la dimension de l'espace ?`),
// ---------- Analyse ----------
faux('ecart-consecutif', 'sup', N, 'ma-07', 'La suite des racines carrées convergerait', T`« Démontrons » que la suite de terme général $u_n = \sqrt n$ converge.`, [
  [T`Pour tout $n$, $u_{n+1} - u_n = \sqrt{n+1} - \sqrt n = \dfrac{1}{\sqrt{n+1} + \sqrt n}$.`, T`C'est exact : on a multiplié et divisé par la quantité conjuguée.`],
  [T`Donc $u_{n+1} - u_n$ tend vers 0.`, T`C'est exact : le dénominateur tend vers $+\infty$.`],
  [T`Une suite dont l'écart entre deux termes consécutifs tend vers 0 est convergente : $(u_n)$ converge.`] ],
  T`Si une suite converge, l'écart entre deux termes consécutifs tend vers 0 ; la réciproque est fausse. Des pas de plus en plus petits peuvent mener aussi loin que l'on veut : $\sqrt n$ tend vers $+\infty$, tout comme $\ln n$ ou les sommes partielles de la série harmonique.`,
  T`$u_{n+1} - u_n \to 0$ est nécessaire à la convergence, pas suffisant. C'est le même phénomène que pour les séries : un terme général qui tend vers 0 ne garantit pas la convergence.`, T`Quelle est la limite de $\sqrt n$ ?`),
faux('extraites', 'sup', N, 'ma-07', 'Une suite alternée qui convergerait', T`« Démontrons » que la suite de terme général $u_n = (-1)^n$ converge.`, [
  [T`La suite extraite $(u_{2n})$ est constante égale à 1 : elle converge.`, T`C'est exact.`],
  [T`La suite extraite $(u_{2n+1})$ est constante égale à $-1$ : elle converge.`, T`C'est exact.`],
  [T`Les termes d'indice pair et ceux d'indice impair recouvrent tous les termes : comme ces deux suites extraites convergent, la suite $(u_n)$ converge.`] ],
  T`Il manque une hypothèse au théorème : les deux suites extraites doivent converger vers la <em>même</em> limite. Ici elles convergent vers 1 et $-1$ : la suite n'a pas de limite, puisque toute suite extraite d'une suite convergente converge vers la même limite qu'elle.`,
  T`Si $(u_{2n})$ et $(u_{2n+1})$ convergent vers un même réel $\ell$, alors $(u_n)$ converge vers $\ell$. Deux suites extraites de limites différentes prouvent au contraire la divergence.`, T`Quelles sont les limites des deux suites extraites ?`),
faux('equivalents-somme', 'sup', N, 'ma-10', '1 = 0 avec des équivalents', T`« Démontrons » que $1 = 0$.`, [
  [T`Quand $n$ tend vers $+\infty$, $n + 1 \sim n$.`, T`C'est exact : le quotient $\dfrac{n+1}{n}$ tend vers 1.`],
  [T`Par ailleurs, $-n \sim -n$.`, T`Toute suite est équivalente à elle-même.`],
  [T`En ajoutant membre à membre ces deux équivalents : $(n + 1) + (-n) \sim n + (-n)$, c'est-à-dire $1 \sim 0$.`],
  [T`Une suite équivalente à la suite nulle est nulle à partir d'un certain rang : donc $1 = 0$.`, T`C'est exact : $u_n \sim 0$ signifie $u_n = 0 \times (1 + \varepsilon_n)$ à partir d'un certain rang. Le passage est correct.` + H] ],
  T`Les équivalents ne s'ajoutent pas. Un équivalent ne retient que le terme dominant ; dans une somme, les termes dominants peuvent se détruire, et ce sont alors les termes négligés qui décident. Les équivalents sont en revanche compatibles avec le produit, le quotient et les puissances fixées.`,
  T`On ne somme pas des équivalents. Pour une somme, on revient aux développements limités ou à la notation $o$, qui gardent la trace de ce que l'on néglige.`, T`Qu'a-t-on négligé en écrivant $n + 1 \sim n$ ?`),
faux('equivalents-exp', 'sup', N, 'ma-10', 'e = 1', T`« Démontrons » que $e = 1$.`, [
  [T`Quand $n$ tend vers $+\infty$, $n + 1 \sim n$.`, T`C'est exact : le quotient tend vers 1.`],
  [T`En composant par l'exponentielle : $e^{n+1} \sim e^{n}$.`],
  [T`Par définition, le quotient $\dfrac{e^{n+1}}{e^n}$ tend donc vers 1.`, T`C'est la définition de deux suites équivalentes, la seconde ne s'annulant pas : le passage est correct.` + H],
  [T`Or ce quotient est constant, égal à $e$ : donc $e = 1$.`, T`Il est exact que $\dfrac{e^{n+1}}{e^n} = e$, et une suite constante a pour limite sa valeur : le passage est correct.` + H] ],
  T`On ne compose pas un équivalent par une fonction. Pour l'exponentielle, $e^{u_n} \sim e^{v_n}$ équivaut à $u_n - v_n \to 0$, ce qui est bien plus fort que $u_n \sim v_n$ : ici la différence vaut 1. La même prudence s'impose pour le logarithme.`,
  T`$e^{u_n} \sim e^{v_n}$ si et seulement si $u_n - v_n \to 0$. Les seules opérations sûres sur les équivalents sont le produit, le quotient et la puissance d'exposant fixé.`, T`Calculez le quotient $\dfrac{e^{n+1}}{e^n}$.`),
faux('bornes-atteintes', 'sup', N, 'ma-08', 'Une borne supérieure atteinte', T`Soit $f$ la fonction $x \mapsto x$ sur l'intervalle $]0, 1[$. « Démontrons » que $1 < 1$.`, [
  [T`La fonction $f$ est continue sur $]0, 1[$, et bornée ; sa borne supérieure est 1.`, T`C'est exact : les valeurs de $f$ sont les réels de $]0, 1[$, dont la borne supérieure est 1.`],
  [T`Une fonction continue sur un intervalle est bornée et atteint ses bornes : il existe $c \in \,]0, 1[$ tel que $f(c) = 1$.`],
  [T`Comme $f(c) = c$, on a $c = 1$. Or $c \in \,]0, 1[$ : donc $1 < 1$.`, T`C'est la définition de $f$, puis celle de l'intervalle ouvert : le passage est correct.` + H] ],
  T`Le théorème des bornes atteintes concerne les fonctions continues sur un <em>segment</em> $[a, b]$, fermé et borné. Sur un intervalle ouvert, une fonction continue peut ne pas atteindre ses bornes, comme ici, ou même ne pas être bornée, comme $x \mapsto \dfrac1x$ sur $]0, 1[$.`,
  T`Toute fonction continue sur un segment est bornée et atteint ses bornes. Les deux mots « continue » et « segment » sont indispensables.`, T`Sur quel type d'intervalle le théorème est-il énoncé ?`),
faux('arctan', 'sup', N, 'ma-05', 'π/2 = −π/2', T`Soit $f(x) = \arctan x + \arctan\dfrac1x$ pour $x \neq 0$. « Démontrons » que $\dfrac{\pi}{2} = -\dfrac{\pi}{2}$.`, [
  [T`La fonction $f$ est dérivable sur $\mathbb{R}^*$, et $f'(x) = \dfrac{1}{1 + x^2} + \dfrac{-\frac{1}{x^2}}{1 + \frac{1}{x^2}} = \dfrac{1}{1 + x^2} - \dfrac{1}{x^2 + 1} = 0$.`, T`Le calcul de la dérivée est exact.`],
  [T`Une fonction de dérivée nulle est constante : $f$ est constante sur $\mathbb{R}^*$.`],
  [T`On a $f(1) = \dfrac{\pi}{4} + \dfrac{\pi}{4} = \dfrac{\pi}{2}$.`, T`C'est exact : $\arctan 1 = \dfrac{\pi}{4}$.`],
  [T`On a $f(-1) = -\dfrac{\pi}{4} - \dfrac{\pi}{4} = -\dfrac{\pi}{2}$.`, T`C'est exact : la fonction arctangente est impaire.`],
  [T`Donc $\dfrac{\pi}{2} = -\dfrac{\pi}{2}$.`, T`Une fonction constante prend la même valeur en 1 et en $-1$ : le passage est correct.` + H] ],
  T`Une fonction de dérivée nulle est constante <em>sur un intervalle</em>. Or $\mathbb{R}^*$ n'est pas un intervalle, mais la réunion de deux intervalles : $f$ est constante sur chacun, avec deux constantes différentes, $\dfrac{\pi}{2}$ sur $]0, +\infty[$ et $-\dfrac{\pi}{2}$ sur $]-\infty, 0[$. La démonstration du théorème, par les accroissements finis, utilise le segment $[x, y]$ tout entier.`,
  T`« $f' = 0$ donc $f$ constante » se dit toujours « sur un intervalle ». Sur une réunion d'intervalles, il y a une constante par intervalle.`, T`L'ensemble $\mathbb{R}^*$ est-il un intervalle ?`),
faux('rolle-complexe', 'sup', N, 'ma-09', 'Rolle pour une fonction complexe', T`Soit $f : [0, 2\pi] \to \mathbb{C}$, $t \mapsto e^{it}$. « Démontrons » que $1 = 0$.`, [
  [T`La fonction $f$ est continue sur $[0, 2\pi]$, dérivable sur $]0, 2\pi[$, et $f'(t) = ie^{it}$.`, T`C'est exact.`],
  [T`On a $f(0) = f(2\pi) = 1$.`, T`C'est exact.`],
  [T`D'après le théorème de Rolle, il existe $c \in \,]0, 2\pi[$ tel que $f'(c) = 0$.`],
  [T`Or $|f'(c)| = |i| \times |e^{ic}| = 1$ : donc $1 = 0$.`, T`Le module de $ie^{ic}$ vaut bien 1, et le module de 0 est 0 : le passage est correct.` + H] ],
  T`Le théorème de Rolle ne vaut que pour les fonctions à valeurs <em>réelles</em> : sa démonstration cherche un maximum ou un minimum de $f$, ce qui n'a pas de sens dans $\mathbb{C}$. On peut l'appliquer à la partie réelle et à la partie imaginaire, mais leurs dérivées s'annulent en des points différents : celle de $\cos$ en $\pi$, celle de $\sin$ en $\dfrac{\pi}{2}$ et en $\dfrac{3\pi}{2}$. Pour les fonctions complexes, il ne subsiste que l'<em>inégalité</em> des accroissements finis.`,
  T`Rolle et l'égalité des accroissements finis sont des théorèmes sur les fonctions réelles. Pour une fonction à valeurs complexes, on dispose de l'inégalité $|f(b) - f(a)| \leqslant M\,|b - a|$.`, T`Où la démonstration du théorème de Rolle utilise-t-elle l'ordre des réels ?`),
faux('changement-variable', 'sup', N, 'ma-18', 'π/2 = 0', T`On pose $I = \displaystyle\int_{-1}^{1} \frac{dx}{1 + x^2}$. « Démontrons » que $\dfrac{\pi}{2} = 0$.`, [
  [T`On a $I = \bigl[\arctan x\bigr]_{-1}^{1} = \dfrac{\pi}{4} + \dfrac{\pi}{4} = \dfrac{\pi}{2}$.`, T`C'est exact : $\arctan$ est une primitive de la fonction intégrée, continue sur $[-1, 1]$.`],
  [T`Effectuons le changement de variable $x = \dfrac1u$, pour lequel $dx = -\dfrac{du}{u^2}$ ; quand $x$ vaut $-1$ ou 1, $u$ vaut $-1$ ou 1. Donc $I = \displaystyle\int_{-1}^{1} \frac{1}{1 + \frac{1}{u^2}} \times \left(-\frac{1}{u^2}\right) du$.`],
  [T`En simplifiant : $I = -\displaystyle\int_{-1}^{1} \frac{du}{u^2 + 1} = -I$.`, T`La simplification $\dfrac{1}{1 + \frac{1}{u^2}} \times \dfrac{1}{u^2} = \dfrac{1}{u^2 + 1}$ est exacte, et l'on reconnaît $I$ : le passage est correct.` + H],
  [T`Donc $2I = 0$, puis $I = 0$, c'est-à-dire $\dfrac{\pi}{2} = 0$.`, T`De $I = -I$ on tire bien $I = 0$ : le passage est correct.` + H] ],
  T`Le théorème de changement de variable demande une fonction $\varphi$ de classe $\mathcal{C}^1$ sur le segment décrit par la nouvelle variable. Or $u \mapsto \dfrac1u$ n'est pas définie en 0, qui est entre $-1$ et 1. Quand $u$ parcourt $[-1, 1]$ privé de 0, $x = \dfrac1u$ ne parcourt pas $[-1, 1]$, mais tout ce qui est en dehors de $]-1, 1[$.`,
  T`Dans $\displaystyle\int_{\varphi(a)}^{\varphi(b)} f(x)\,dx = \int_a^b f(\varphi(u))\,\varphi'(u)\,du$, la fonction $\varphi$ doit être de classe $\mathcal{C}^1$ sur $[a, b]$ tout entier. Vérifier les bornes ne suffit pas.`, T`La fonction $u \mapsto \dfrac1u$ est-elle définie sur tout l'intervalle d'intégration ?`),
faux('rearrangement', 'sup', N, 'ma-20', 'Changer l\'ordre des termes', T`On admet que la série $1 - \dfrac12 + \dfrac13 - \dfrac14 + \dots$ converge, et que sa somme $S$ n'est pas nulle (elle vaut $\ln 2$). « Démontrons » que $1 = \dfrac12$.`, [
  [T`Changeons l'ordre des termes, en faisant suivre chaque terme positif de deux termes négatifs : $S = 1 - \dfrac12 - \dfrac14 + \dfrac13 - \dfrac16 - \dfrac18 + \dfrac15 - \dfrac1{10} - \dfrac1{12} + \dots$`],
  [T`Regroupons chaque terme positif avec le terme négatif qui le suit : $S = \left(1 - \dfrac12\right) - \dfrac14 + \left(\dfrac13 - \dfrac16\right) - \dfrac18 + \left(\dfrac15 - \dfrac1{10}\right) - \dfrac1{12} + \dots$`, T`Regrouper par paquets d'un ou deux termes consécutifs une série dont le terme général tend vers 0 ne change ni sa nature ni sa somme : le passage est correct.` + H],
  [T`Donc $S = \dfrac12 - \dfrac14 + \dfrac16 - \dfrac18 + \dfrac1{10} - \dfrac1{12} + \dots = \dfrac12\left(1 - \dfrac12 + \dfrac13 - \dfrac14 + \dots\right)$.`, T`Les parenthèses sont bien calculées, et l'on peut mettre $\dfrac12$ en facteur dans une série convergente : le passage est correct.` + H],
  [T`Ainsi $S = \dfrac12 S$. Comme $S \neq 0$, on en déduit $1 = \dfrac12$.`, T`On reconnaît la série de départ, et la division par $S \neq 0$ est permise : le passage est correct.` + H] ],
  T`La somme d'une série dépend en général de l'ordre de ses termes : une série n'est pas une somme finie, mais la limite de ses sommes partielles, et changer l'ordre change les sommes partielles. La série réordonnée converge bien, mais vers $\dfrac12\ln 2$. On ne peut permuter librement les termes que si la série est <em>absolument</em> convergente, ce qui n'est pas le cas ici : la série des valeurs absolues est la série harmonique.`,
  T`La commutativité de l'addition ne s'étend pas aux séries. Seules les séries absolument convergentes ont une somme indépendante de l'ordre des termes (résultat hors programme de première année, admis ici).`, T`La série des valeurs absolues converge-t-elle ?`),
faux('comparaison-signe', 'sup', N, 'ma-20', 'La série harmonique convergerait', T`« Démontrons » que la série harmonique $\sum \dfrac1n$ converge.`, [
  [T`Pour tout entier $n \geqslant 1$, on a $-\dfrac1n \leqslant \dfrac{1}{n^2}$.`, T`C'est exact : le membre de gauche est négatif, celui de droite positif.`],
  [T`La série $\sum \dfrac{1}{n^2}$ converge.`, T`C'est une série de Riemann d'exposant $2 > 1$.`],
  [T`Par comparaison, la série $\sum \left(-\dfrac1n\right)$ converge.`],
  [T`En multipliant par $-1$ : la série $\sum \dfrac1n$ converge.`, T`Multiplier le terme général par une constante non nulle ne change pas la nature d'une série : le passage est correct.` + H] ],
  T`Le théorème de comparaison exige $0 \leqslant u_n \leqslant v_n$ : il s'applique aux séries à termes <em>positifs</em>. C'est la positivité qui rend croissante la suite des sommes partielles, et permet de conclure dès qu'elle est majorée. Ici les sommes partielles de $\sum\left(-\dfrac1n\right)$ sont bien majorées, mais elles décroissent vers $-\infty$.`,
  T`Les théorèmes de comparaison, d'équivalence et de domination sont des théorèmes sur les séries à termes positifs. Pour un signe quelconque, on passe par la convergence absolue.`, T`Quel est le signe du terme général de la série que l'on compare ?`),
// ---------- Probabilités ----------
faux('deux-a-deux-independants', 'sup', Pr, 'ma-21', 'Indépendants deux à deux', T`On lance deux fois une pièce équilibrée. On note $A$ « le premier lancer donne pile », $B$ « le second lancer donne pile » et $C$ « les deux lancers donnent le même résultat ». « Démontrons » que $\dfrac14 = \dfrac18$.`, [
  [T`On a $P(A) = P(B) = P(C) = \dfrac12$.`, T`C'est exact : parmi les quatre issues équiprobables, deux réalisent chaque événement.`],
  [T`On a $P(A \cap B) = P(A \cap C) = P(B \cap C) = \dfrac14$ : les événements $A$, $B$, $C$ sont deux à deux indépendants.`, T`C'est exact : chacune de ces trois intersections est l'événement « pile, pile », et $\dfrac14 = \dfrac12 \times \dfrac12$.`],
  [T`Ils sont donc mutuellement indépendants : $P(A \cap B \cap C) = P(A)\,P(B)\,P(C) = \dfrac18$.`],
  [T`Or $A \cap B \cap C$ est l'événement « pile, pile », de probabilité $\dfrac14$ : donc $\dfrac14 = \dfrac18$.`, T`L'intersection est bien identifiée et sa probabilité est exacte : le passage est correct.` + H] ],
  T`L'indépendance deux à deux n'entraîne pas l'indépendance mutuelle, qui demande la formule du produit pour <em>toutes</em> les sous-familles, y compris la famille entière. Ici, deux quelconques des événements déterminent le troisième : si $A$ et $B$ sont réalisés, $C$ l'est à coup sûr.`,
  T`Indépendance mutuelle de $A$, $B$, $C$ : quatre égalités, une par paire et une pour le triplet. Les trois premières ne donnent pas la quatrième.`, T`Si l'on sait que $A$ et $B$ sont réalisés, que sait-on de $C$ ?`),
faux('esperance-produit', 'sup', Pr, 'ma-21', '1 = 0 avec une espérance', T`Soit $X$ une variable aléatoire qui prend les valeurs 1 et $-1$ avec la probabilité $\dfrac12$ chacune. « Démontrons » que $1 = 0$.`, [
  [T`On a $E(X) = 1 \times \dfrac12 + (-1) \times \dfrac12 = 0$.`, T`Le calcul est exact.`],
  [T`La variable $X^2$ est constante égale à 1 : donc $E(X^2) = 1$.`, T`C'est exact : $1^2 = (-1)^2 = 1$.`],
  [T`L'espérance d'un produit est le produit des espérances : $E(X \times X) = E(X) \times E(X)$.`],
  [T`Donc $1 = 0 \times 0 = 0$.`, T`On a remplacé chaque espérance par sa valeur, calculée plus haut : le passage est correct.` + H] ],
  T`La formule $E(XY) = E(X)\,E(Y)$ suppose $X$ et $Y$ <em>indépendantes</em>, et une variable non constante n'est jamais indépendante d'elle-même. L'écart $E(X^2) - E(X)^2$ est précisément la variance de $X$, qui vaut ici 1.`,
  T`L'espérance est toujours linéaire, $E(X + Y) = E(X) + E(Y)$ ; elle n'est multiplicative que pour des variables indépendantes.`, T`Les deux facteurs du produit sont-ils indépendants ?`),
faux('variance-difference', 'sup', Pr, 'ma-21', 'Deux dés toujours égaux', T`On lance deux dés équilibrés indépendants, et l'on note $X$ et $Y$ leurs résultats. « Démontrons » que les deux dés donnent presque sûrement le même résultat.`, [
  [T`Les variables $X$ et $Y$ ont la même loi : $E(X) = E(Y)$ et $V(X) = V(Y)$.`, T`C'est exact : deux variables de même loi ont même espérance et même variance.`],
  [T`Par linéarité de l'espérance, $E(X - Y) = E(X) - E(Y) = 0$.`, T`C'est exact : la linéarité de l'espérance ne demande aucune hypothèse.`],
  [T`Comme $X$ et $Y$ sont indépendantes, $V(X - Y) = V(X) - V(Y) = 0$.`],
  [T`Une variable aléatoire de variance nulle est presque sûrement égale à son espérance : $X - Y = 0$ presque sûrement.`, T`C'est un résultat du cours, conséquence de l'inégalité de Bienaymé-Tchebychev : le passage est correct.` + H] ],
  T`La variance n'est pas linéaire : $V(aX) = a^2 V(X)$, donc $V(-Y) = V(Y)$. Pour des variables indépendantes, $V(X - Y) = V(X) + V(-Y) = V(X) + V(Y)$ : les variances s'ajoutent, même pour une différence. Ici $V(X - Y) = \dfrac{35}{12} + \dfrac{35}{12} = \dfrac{35}{6}$.`,
  T`Pour $X$ et $Y$ indépendantes, $V(X \pm Y) = V(X) + V(Y)$. Retrancher une variable aléatoire ajoute de la dispersion, cela n'en enlève jamais.`, T`Que vaut $V(-Y)$ en fonction de $V(Y)$ ?`),
// ---------- Ajouts du 12 nov. (audit des chapitres, §147) ----------
faux('negation-universelle', 'sup', F, 'ma-01', 'Une négation mal formée', T`« Démontrons » que $1 \leqslant 0$.`, [
  [T`L'énoncé « pour tout réel $x$, $x^2 > 0$ » est faux, puisque $0^2 = 0$.`, T`C'est exact : un seul contre-exemple suffit à réfuter un énoncé universel.`],
  [T`Sa négation est donc vraie. Or la négation de « pour tout réel $x$, $x^2 > 0$ » est « pour tout réel $x$, $x^2 \leqslant 0$ ».`],
  [T`En particulier, pour $x = 1$ : $1 \leqslant 0$.`, T`Un énoncé vrai pour tout réel $x$ l'est pour $x = 1$ : le passage est correct.` + H] ],
  T`La négation de « pour tout $x$, $P(x)$ » est « <em>il existe</em> $x$ tel que non $P(x)$ » : il faut changer le quantificateur, et pas seulement nier la propriété. La négation correcte, « il existe un réel $x$ tel que $x^2 \leqslant 0$ », est bien vraie, grâce à $x = 0$.`,
  T`$\text{non}(\forall x,\ P(x))$ équivaut à $\exists x,\ \text{non}\,P(x)$, et $\text{non}(\exists x,\ P(x))$ équivaut à $\forall x,\ \text{non}\,P(x)$.`, T`Que faut-il pour qu'un énoncé « pour tout » soit faux ?`),
faux('image-reciproque', 'sup', F, 'ma-02', 'Image réciproque de l\'image', T`Soit $f : \mathbb{R} \to \mathbb{R}$, $x \mapsto x^2$, et $A = [0, 1]$. « Démontrons » que $-1 \geqslant 0$.`, [
  [T`On a $f(A) = [0, 1]$.`, T`C'est exact : le carré d'un réel de $[0, 1]$ décrit $[0, 1]$.`],
  [T`On a $f^{-1}\bigl([0, 1]\bigr) = [-1, 1]$.`, T`C'est exact : $x^2 \in [0, 1]$ équivaut à $-1 \leqslant x \leqslant 1$.`],
  [T`Pour toute partie $A$ de l'ensemble de départ, $f^{-1}\bigl(f(A)\bigr) = A$.`],
  [T`Donc $[-1, 1] = [0, 1]$ : en particulier $-1 \in [0, 1]$, et $-1 \geqslant 0$.`, T`On a remplacé chaque membre par sa valeur, calculée plus haut : le passage est correct.` + H] ],
  T`On a seulement l'inclusion $A \subset f^{-1}\bigl(f(A)\bigr)$ : l'image réciproque de $f(A)$ contient tous les éléments qui ont la même image qu'un élément de $A$. L'égalité a lieu pour toute partie $A$ si et seulement si $f$ est injective. De même, $f\bigl(f^{-1}(B)\bigr) \subset B$, avec égalité pour toute partie $B$ si et seulement si $f$ est surjective.`,
  T`$A \subset f^{-1}(f(A))$ et $f(f^{-1}(B)) \subset B$. La notation $f^{-1}(B)$ désigne une image réciproque, qui existe même quand $f$ n'est pas bijective.`, T`Quels sont tous les réels dont le carré est dans $[0, 1]$ ?`),
faux('somme-produit', 'sup', F, 'ma-03', '5 = 9 avec des sommes', T`« Démontrons » que $5 = 9$.`, [
  [T`On a $\displaystyle\sum_{k=1}^{2} k^2 = 1 + 4 = 5$.`, T`Le calcul est exact.`],
  [T`Comme $k^2 = k \times k$, la somme des produits est le produit des sommes : $\displaystyle\sum_{k=1}^{2} k \times k = \left(\sum_{k=1}^{2} k\right) \times \left(\sum_{k=1}^{2} k\right)$.`],
  [T`Or $\displaystyle\sum_{k=1}^{2} k = 3$ : le produit vaut 9. Donc $5 = 9$.`, T`La somme et le produit sont bien calculés : le passage est correct.` + H] ],
  T`Le symbole $\sum$ est linéaire : il se comporte bien avec l'addition et la multiplication par une constante, pas avec le produit de deux termes qui dépendent de l'indice. Le produit de deux sommes est une somme <em>double</em> : $\left(\displaystyle\sum_i a_i\right)\left(\displaystyle\sum_j b_j\right) = \displaystyle\sum_i \sum_j a_i b_j$, qui contient les termes croisés $a_i b_j$ avec $i \neq j$.`,
  T`$\displaystyle\sum (a_k + b_k) = \sum a_k + \sum b_k$, mais $\displaystyle\sum a_k b_k \neq \left(\sum a_k\right)\left(\sum b_k\right)$ en général.`, T`Développez $(1 + 2)(1 + 2)$ : combien de termes obtenez-vous ?`),
faux('carre-neutre', 'sup', A, 'ma-11', 'Simplifier dans un groupe', T`Dans le groupe $(\{-1, 1\}, \times)$, d'élément neutre 1, « démontrons » que $-1 = 1$.`, [
  [T`On a $(-1) \times (-1) = 1$ et $1 \times 1 = 1$.`, T`Les deux produits sont exacts.`],
  [T`Donc $(-1) \times (-1) = 1 \times 1$.`, T`Deux nombres égaux à 1 sont égaux entre eux.`],
  [T`Dans un groupe, tout élément est simplifiable : de $x \times x = e \times e$, on déduit $x = e$. Donc $-1 = 1$.`] ],
  T`Simplifier, dans un groupe, c'est supprimer un <em>même</em> élément placé du même côté dans les deux membres : $ax = ay$ entraîne $x = y$. Dans $x \times x = e \times e$, les facteurs des deux membres sont différents, et il n'y a rien à simplifier. Un élément dont le carré est le neutre n'est pas forcément le neutre : il est seulement égal à son inverse.`,
  T`$ax = ay \Rightarrow x = y$ et $xa = ya \Rightarrow x = y$. En revanche $x^2 = y^2$ n'entraîne pas $x = y$, même dans un groupe commutatif.`, T`Quel élément exactement veut-on simplifier, et de quel côté ?`),
faux('zn-corps', 'sup', A, 'ma-11', 'ℤ/4ℤ serait un corps', T`« Démontrons » que 4 divise 2.`, [
  [T`Pour tout entier $n \geqslant 2$, l'anneau $\mathbb{Z}/n\mathbb{Z}$ est un corps ; en particulier $\mathbb{Z}/4\mathbb{Z}$ est un corps.`],
  [T`Un corps est un anneau intègre : dans $\mathbb{Z}/4\mathbb{Z}$, un produit n'est nul que si l'un de ses facteurs est nul.`, T`Il est exact que tout corps est intègre : si $ab = 0$ et $a \neq 0$, on multiplie par l'inverse de $a$. Le passage est correct.` + H],
  [T`Or, dans $\mathbb{Z}/4\mathbb{Z}$, $\overline2 \times \overline2 = \overline4 = \overline0$ : donc $\overline2 = \overline0$.`, T`Le produit est bien calculé, et l'on applique la ligne précédente : le passage est correct.` + H],
  [T`Autrement dit, 4 divise 2.`, T`C'est la traduction de $\overline2 = \overline0$ dans $\mathbb{Z}/4\mathbb{Z}$ : le passage est correct.` + H] ],
  T`L'anneau $\mathbb{Z}/n\mathbb{Z}$ est un corps si et seulement si $n$ est <em>premier</em>. Si $n = ab$ avec $1 < a, b < n$, les classes de $a$ et $b$ sont non nulles et de produit nul : l'anneau n'est même pas intègre. Les éléments inversibles de $\mathbb{Z}/n\mathbb{Z}$ sont les classes des entiers premiers avec $n$.`,
  T`$\mathbb{Z}/n\mathbb{Z}$ est un corps $\iff$ $\mathbb{Z}/n\mathbb{Z}$ est intègre $\iff$ $n$ est premier.`, T`La classe de 2 a-t-elle un inverse dans $\mathbb{Z}/4\mathbb{Z}$ ?`),
faux('degre-composee', 'sup', A, 'ma-13', '6 = 5 avec des degrés', T`Soit $P = X^3$ et $Q = X^2$. « Démontrons » que $6 = 5$.`, [
  [T`Le polynôme composé $P \circ Q$ est $(X^2)^3 = X^6$, de degré 6.`, T`Le calcul est exact.`],
  [T`Le degré d'une composée est la somme des degrés : $\deg(P \circ Q) = \deg P + \deg Q = 5$.`],
  [T`Donc $6 = 5$.`, T`Le degré d'un polynôme est unique : le passage est correct.` + H] ],
  T`C'est le degré d'un <em>produit</em> qui est la somme des degrés. Pour une composée de polynômes non constants, les degrés se multiplient : $\deg(P \circ Q) = \deg P \times \deg Q$, ici $3 \times 2 = 6$.`,
  T`$\deg(PQ) = \deg P + \deg Q$ et, pour $Q$ non constant, $\deg(P \circ Q) = \deg P \times \deg Q$.`, T`Comparez $X^3 \times X^2$ et $(X^2)^3$.`),
faux('argument-somme', 'sup', A, 'ma-04', '1 = 2 avec des arguments', T`« Démontrons » que $1 = 2$.`, [
  [T`Un argument de 1 est 0, et un argument de $i$ est $\dfrac{\pi}{2}$.`, T`Les deux valeurs sont exactes.`],
  [T`L'argument d'une somme est la somme des arguments : un argument de $1 + i$ est $0 + \dfrac{\pi}{2} = \dfrac{\pi}{2}$.`],
  [T`Or $1 + i = \sqrt2\,e^{i\pi/4}$ : un argument de $1 + i$ est $\dfrac{\pi}{4}$, et c'est le seul dans $]-\pi, \pi]$, intervalle qui contient aussi $\dfrac{\pi}{2}$.`, T`La forme exponentielle de $1 + i$ est exacte, et deux arguments d'un même nombre diffèrent d'un multiple de $2\pi$.`],
  [T`Donc $\dfrac{\pi}{2} = \dfrac{\pi}{4}$, et, en multipliant par $\dfrac{4}{\pi}$ : $2 = 1$.`, T`Deux arguments d'un même nombre situés dans $]-\pi, \pi]$ sont égaux : le passage est correct.` + H] ],
  T`L'argument transforme les <em>produits</em> en sommes : $\arg(zz') \equiv \arg z + \arg z' \pmod{2\pi}$. Pour la somme de deux complexes, il n'y a pas de formule : géométriquement, on additionne des vecteurs, et la direction de la somme dépend aussi des modules.`,
  T`$|zz'| = |z|\,|z'|$ et $\arg(zz') \equiv \arg z + \arg z'$ : la forme exponentielle est faite pour les produits, la forme algébrique pour les sommes.`, T`Placez les points d'affixes 1, $i$ et $1 + i$.`),
faux('supplementaire-unique', 'sup', L, 'ma-14', 'Le supplémentaire', T`Dans $\mathbb{R}^2$, soit $F$ la droite engendrée par $(1, 0)$, $G_1$ la droite engendrée par $(0, 1)$ et $G_2$ la droite engendrée par $(1, 1)$. « Démontrons » que $0 = 1$.`, [
  [T`Les sous-espaces $F$ et $G_1$ sont supplémentaires dans $\mathbb{R}^2$.`, T`C'est exact : $\bigl((1, 0), (0, 1)\bigr)$ est une base de $\mathbb{R}^2$.`],
  [T`Les sous-espaces $F$ et $G_2$ sont supplémentaires dans $\mathbb{R}^2$.`, T`C'est exact : $\bigl((1, 0), (1, 1)\bigr)$ est une base de $\mathbb{R}^2$.`],
  [T`Un sous-espace a un seul supplémentaire : donc $G_1 = G_2$.`],
  [T`Le vecteur $(0, 1)$ de $G_1$ appartient donc à $G_2$ : il existe $\lambda$ tel que $(0, 1) = (\lambda, \lambda)$, d'où $\lambda = 0$ et $\lambda = 1$, soit $0 = 1$.`, T`Les vecteurs de $G_2$ sont les $(\lambda, \lambda)$, et l'on identifie les coordonnées : le passage est correct.` + H] ],
  T`Un sous-espace a en général une infinité de supplémentaires : toute droite du plan autre que $F$ est un supplémentaire de $F$. C'est pourquoi l'on dit « un » supplémentaire et non « le » supplémentaire. Ce qui est unique, une fois le supplémentaire choisi, c'est la décomposition de chaque vecteur.`,
  T`Le supplémentaire n'est pas le complémentaire, et il n'est pas unique. Dans un espace préhilbertien, un sous-espace de dimension finie en possède un qui est privilégié : son supplémentaire orthogonal.`, T`Combien de droites du plan sont en somme directe avec $F$ ?`),
faux('non-nulle-inversible', 'sup', L, 'ma-16', 'Non nulle, donc inversible ?', T`Soit $A = \begin{pmatrix} 1 & 1 \\ 1 & 1 \end{pmatrix}$ et $X = \begin{pmatrix} 1 \\ -1 \end{pmatrix}$. « Démontrons » que $1 = 0$.`, [
  [T`On a $AX = \begin{pmatrix} 1 - 1 \\ 1 - 1 \end{pmatrix} = \begin{pmatrix} 0 \\ 0 \end{pmatrix}$.`, T`Le produit est bien calculé.`],
  [T`La matrice $A$ n'est pas nulle : elle est donc inversible.`],
  [T`En multipliant $AX = 0$ à gauche par $A^{-1}$ : $X = 0$.`, T`Si $A$ est inversible, $A^{-1}AX = X$ et $A^{-1} \times 0 = 0$ : le passage est correct.` + H],
  [T`Le premier coefficient de $X$ donne $1 = 0$.`, T`Deux colonnes égales ont les mêmes coefficients : le passage est correct.` + H] ],
  T`Parmi les nombres, tout élément non nul a un inverse ; parmi les matrices, ce n'est plus vrai. La matrice $A$ a deux colonnes égales, son déterminant est nul : elle n'est pas inversible. L'existence d'une colonne $X$ non nulle telle que $AX = 0$ en est d'ailleurs une preuve directe.`,
  T`Une matrice carrée $A$ est inversible si et seulement si $AX = 0$ n'a que la solution $X = 0$, ou encore si et seulement si $\det A \neq 0$.`, T`Calculez le déterminant de $A$.`),
faux('echange-lignes', 'sup', L, 'ma-17', '1 = −1 avec un déterminant', T`« Démontrons » que $1 = -1$.`, [
  [T`On a $\det\begin{pmatrix} 1 & 0 \\ 0 & 1 \end{pmatrix} = 1$.`, T`C'est exact : $1 \times 1 - 0 \times 0 = 1$.`],
  [T`En échangeant les deux lignes de cette matrice, on obtient $\begin{pmatrix} 0 & 1 \\ 1 & 0 \end{pmatrix}$, de déterminant $0 \times 0 - 1 \times 1 = -1$.`, T`L'échange et le calcul sont exacts.`],
  [T`Les opérations élémentaires sur les lignes ne changent pas le déterminant : les deux matrices ont le même déterminant.`],
  [T`Donc $1 = -1$.`, T`On a comparé les deux déterminants calculés plus haut : le passage est correct.` + H] ],
  T`Seule l'une des trois opérations élémentaires conserve le déterminant : ajouter à une ligne un multiple d'une autre. Échanger deux lignes le multiplie par $-1$, et multiplier une ligne par $\lambda$ le multiplie par $\lambda$. Ce que toutes conservent, c'est le <em>rang</em>, et donc le caractère inversible.`,
  T`$L_i \leftarrow L_i + \lambda L_j$ : déterminant inchangé. $L_i \leftrightarrow L_j$ : déterminant changé de signe. $L_i \leftarrow \lambda L_i$ : déterminant multiplié par $\lambda$.`, T`Quelles opérations élémentaires laissent le déterminant inchangé ?`),
faux('orthogonal-intersection', 'sup', L, 'ma-19', 'L\'orthogonal d\'une intersection', T`Dans $\mathbb{R}^2$ muni du produit scalaire usuel, soit $F$ la droite engendrée par $(1, 0)$ et $G$ la droite engendrée par $(0, 1)$. « Démontrons » que $\mathbb{R}^2 = \{0\}$.`, [
  [T`On a $F \cap G = \{0\}$, donc $(F \cap G)^\perp = \mathbb{R}^2$.`, T`C'est exact : tout vecteur est orthogonal au vecteur nul.`],
  [T`On a $F^\perp = G$ et $G^\perp = F$, donc $F^\perp \cap G^\perp = G \cap F = \{0\}$.`, T`C'est exact : les deux axes sont orthogonaux l'un à l'autre.`],
  [T`L'orthogonal d'une intersection est l'intersection des orthogonaux : $(F \cap G)^\perp = F^\perp \cap G^\perp$.`],
  [T`Donc $\mathbb{R}^2 = \{0\}$.`, T`On a remplacé chaque membre par sa valeur, calculée plus haut : le passage est correct.` + H] ],
  T`Passer à l'orthogonal renverse les inclusions, et échange donc somme et intersection : $(F + G)^\perp = F^\perp \cap G^\perp$, et, en dimension finie, $(F \cap G)^\perp = F^\perp + G^\perp$. Ici $F^\perp + G^\perp = G + F = \mathbb{R}^2$, comme attendu.`,
  T`$(F + G)^\perp = F^\perp \cap G^\perp$ : être orthogonal à $F + G$, c'est être orthogonal à $F$ et à $G$. Plus un sous-espace est petit, plus son orthogonal est grand.`, T`Si $F$ rétrécit, que devient son orthogonal ?`),
faux('superposition', 'sup', N, 'ma-06', 'Superposer avec un second membre', T`On considère l'équation différentielle $(E) : y' + y = 1$. « Démontrons » que $2 = 1$.`, [
  [T`La fonction constante égale à 1 est solution de $(E)$ : sa dérivée est nulle, et $0 + 1 = 1$.`, T`La vérification est exacte.`],
  [T`L'équation $(E)$ est linéaire : la somme de deux solutions est une solution. La fonction constante $1 + 1 = 2$ est donc solution de $(E)$.`],
  [T`En reportant dans l'équation : $0 + 2 = 1$, c'est-à-dire $2 = 1$.`, T`La dérivée d'une constante est nulle, et l'on écrit que la fonction vérifie $(E)$ : le passage est correct.` + H] ],
  T`Le principe de superposition, sous cette forme, ne vaut que pour l'équation <em>homogène</em> $y' + y = 0$, dont les solutions forment un espace vectoriel. Avec un second membre, la somme de deux solutions vérifie $y' + y = 2$. C'est la <em>différence</em> de deux solutions de $(E)$ qui est solution de l'équation homogène.`,
  T`Solutions de l'équation avec second membre = une solution particulière + toutes les solutions de l'équation homogène. Elles forment un espace affine, pas un espace vectoriel.`, T`La fonction nulle est-elle solution de $(E)$ ?`),
faux('interversion-limites', 'sup', N, 'ma-08', 'Intervertir deux limites', T`« Démontrons » que $1 = 0$, à l'aide des nombres $x^n$, pour $x \in [0, 1[$ et $n$ entier.`, [
  [T`Pour $n$ fixé, $x^n$ tend vers 1 quand $x$ tend vers 1 : donc $\displaystyle\lim_{n \to +\infty}\ \lim_{x \to 1^-} x^n = 1$.`, T`C'est exact : pour chaque $n$, la limite intérieure vaut 1, et la suite constante égale à 1 tend vers 1.`],
  [T`Pour $x$ fixé dans $[0, 1[$, $x^n$ tend vers 0 quand $n$ tend vers $+\infty$ : donc $\displaystyle\lim_{x \to 1^-}\ \lim_{n \to +\infty} x^n = 0$.`, T`C'est exact : pour chaque $x$ de $[0, 1[$, la limite intérieure vaut 0, et la fonction nulle tend vers 0.`],
  [T`On peut échanger l'ordre de deux passages à la limite : les deux nombres précédents sont égaux.`],
  [T`Donc $1 = 0$.`, T`On a comparé les deux limites calculées plus haut : le passage est correct.` + H] ],
  T`Deux passages à la limite ne commutent pas en général : le résultat dépend de l'ordre. Ici, pour $n$ grand et $x$ proche de 1, $x^n$ peut être proche de n'importe quelle valeur entre 0 et 1, selon la vitesse à laquelle chacun des deux s'approche de sa limite. L'interversion demande des hypothèses supplémentaires, étudiées en deuxième année.`,
  T`$\displaystyle\lim_n \lim_x$ et $\displaystyle\lim_x \lim_n$ sont deux nombres différents a priori. Il en va de même pour une limite et une intégrale, ou une limite et une dérivée.`, T`Que vaut $x^n$ pour $x = 1 - \dfrac1n$ et $n$ grand ?`),
faux('strictement-croissante', 'sup', N, 'ma-09', '0 > 0 avec une dérivée', T`Soit $f : x \mapsto x^3$. « Démontrons » que $0 > 0$.`, [
  [T`La fonction $f$ est strictement croissante sur $\mathbb{R}$.`, T`C'est exact : si $x < y$, alors $x^3 < y^3$.`],
  [T`Une fonction dérivable et strictement croissante sur un intervalle a une dérivée strictement positive en tout point : en particulier $f'(0) > 0$.`],
  [T`Or $f'(x) = 3x^2$, donc $f'(0) = 0$ : ainsi $0 > 0$.`, T`La dérivée est exacte : le passage est correct.` + H] ],
  T`L'implication vraie est la réciproque : si $f' > 0$ sur un intervalle, alors $f$ est strictement croissante. Une fonction strictement croissante peut avoir une dérivée nulle en certains points ; on sait seulement que $f' \geqslant 0$. Plus précisément, $f$ est strictement croissante si et seulement si $f' \geqslant 0$ et $f'$ ne s'annule sur aucun intervalle non réduit à un point.`,
  T`Pour $f$ dérivable sur un intervalle : $f' > 0 \Rightarrow f$ strictement croissante ; $f$ croissante $\iff f' \geqslant 0$. La stricte croissance n'interdit pas les tangentes horizontales isolées.`, T`Quelle est la tangente à la courbe de $f$ en 0 ?`),
faux('dl-produit', 'sup', N, 'ma-10', 'Un ordre de trop', T`« Démontrons » que $1 = 2$, par le développement limité de $e^{2x}$ en 0.`, [
  [T`Au voisinage de 0, $e^x = 1 + x + o(x)$.`, T`C'est le développement limité de l'exponentielle à l'ordre 1.`],
  [T`En élevant au carré : $e^{2x} = (1 + x)^2 + o(x^2) = 1 + 2x + x^2 + o(x^2)$.`],
  [T`Or le développement usuel, appliqué à $2x$, donne $e^{2x} = 1 + 2x + \dfrac{(2x)^2}{2} + o(x^2) = 1 + 2x + 2x^2 + o(x^2)$.`, T`C'est le développement limité de l'exponentielle à l'ordre 2, où l'on a remplacé $x$ par $2x$.`],
  [T`Par unicité du développement limité, les coefficients de $x^2$ sont égaux : $1 = 2$.`, T`Une fonction a au plus un développement limité à un ordre donné : le passage est correct.` + H] ],
  T`On ne gagne pas de précision en calculant : le carré de $1 + x + o(x)$ est $1 + 2x + o(x)$, et rien de plus. Le terme $x^2$ écrit à la ligne 2 est incomplet, car le produit $2 \times 1 \times o(x)$ est seulement un $o(x)$ et contient une contribution en $x^2$ inconnue. Pour obtenir l'ordre 2, il faut partir de $e^x = 1 + x + \dfrac{x^2}{2} + o(x^2)$ : le double produit $2 \times 1 \times \dfrac{x^2}{2}$ fournit le $x^2$ manquant.`,
  T`Dans un produit de développements limités, la précision du résultat est celle du moins précis des facteurs. On fixe l'ordre visé avant de calculer, et l'on tronque tout au même ordre.`, T`À quel ordre connaît-on $e^x$ à la ligne 1 ?`),
faux('valeur-absolue-integrale', 'sup', N, 'ma-18', '1 = 0 avec une intégrale', T`« Démontrons » que $1 = 0$.`, [
  [T`On a $\displaystyle\int_{-1}^{1} x\,dx = 0$.`, T`C'est exact : une primitive est $\dfrac{x^2}{2}$, qui prend la même valeur en $-1$ et en 1.`],
  [T`On a $\displaystyle\int_{-1}^{1} |x|\,dx = 1$.`, T`C'est exact : c'est l'aire de deux triangles d'aire $\dfrac12$.`],
  [T`L'intégrale de la valeur absolue est la valeur absolue de l'intégrale : $\displaystyle\int_{-1}^{1} |x|\,dx = \left|\int_{-1}^{1} x\,dx\right|$.`],
  [T`Donc $1 = |0| = 0$.`, T`On a remplacé chaque intégrale par sa valeur, calculée plus haut : le passage est correct.` + H] ],
  T`On dispose seulement de l'inégalité $\left|\displaystyle\int_a^b f\right| \leqslant \displaystyle\int_a^b |f|$, pour $a \leqslant b$ : c'est l'inégalité triangulaire, étendue des sommes aux intégrales. Il y a égalité quand $f$ garde un signe constant ; sinon, les parties positive et négative se compensent dans le membre de gauche, pas dans celui de droite.`,
  T`$\left|\displaystyle\int_a^b f\right| \leqslant \displaystyle\int_a^b |f|$ pour $a \leqslant b$. La valeur absolue ne « traverse » ni les sommes ni les intégrales.`, T`Quel est le signe de $x$ sur $[-1, 0]$ et sur $[0, 1]$ ?`),
faux('produit-series', 'sup', N, 'ma-20', '3 = 1 avec des séries', T`« Démontrons » que $3 = 1$.`, [
  [T`La série géométrique de raison $\dfrac12$ converge, et $\displaystyle\sum_{n=0}^{+\infty} \frac{1}{2^n} = \frac{1}{1 - \frac12} = 2$.`, T`C'est la somme d'une série géométrique de raison $\dfrac12$.`],
  [T`De même, $\displaystyle\sum_{n=0}^{+\infty} \frac{1}{4^n} = \frac{1}{1 - \frac14} = \frac43$.`, T`C'est la somme d'une série géométrique de raison $\dfrac14$.`],
  [T`Comme $\dfrac{1}{4^n} = \dfrac{1}{2^n} \times \dfrac{1}{2^n}$, la somme des produits est le produit des sommes : $\displaystyle\sum_{n=0}^{+\infty} \frac{1}{4^n} = 2 \times 2 = 4$.`],
  [T`Donc $\dfrac43 = 4$, c'est-à-dire, en multipliant par $\dfrac34$ : $1 = 3$.`, T`On a comparé les deux valeurs obtenues pour la même somme : le passage est correct.` + H] ],
  T`La somme d'une série dont le terme général est un produit $a_n b_n$ n'est pas le produit des sommes : le produit des deux sommes contient tous les termes croisés $a_i b_j$, et pas seulement ceux où $i = j$. La série qui a pour somme le produit des sommes est le <em>produit de Cauchy</em>, de terme général $\displaystyle\sum_{k=0}^{n} a_k b_{n-k}$, sous une hypothèse de convergence absolue.`,
  T`Les sommes de séries sont linéaires ; elles ne sont pas multiplicatives. Pour multiplier deux séries, on utilise le produit de Cauchy.`, T`Que contient le produit $(a_0 + a_1)(b_0 + b_1)$ en plus de $a_0 b_0 + a_1 b_1$ ?`),
faux('partielles-continue', 'sup', N, 'ma-22', 'Des dérivées partielles qui ne suffisent pas', T`Soit $f$ la fonction définie sur $\mathbb{R}^2$ par $f(x, y) = \dfrac{xy}{x^2 + y^2}$ si $(x, y) \neq (0, 0)$, et $f(0, 0) = 0$. « Démontrons » que $\dfrac12 = 0$.`, [
  [T`Pour tout réel $x$, $f(x, 0) = 0$, et pour tout réel $y$, $f(0, y) = 0$ : les deux dérivées partielles de $f$ en $(0, 0)$ existent et sont nulles.`, T`C'est exact : les deux fonctions partielles en $(0, 0)$ sont nulles, donc dérivables.`],
  [T`Une fonction qui admet des dérivées partielles en un point est continue en ce point : $f$ est continue en $(0, 0)$.`],
  [T`En particulier, $f(t, t)$ tend vers $f(0, 0) = 0$ quand $t$ tend vers 0.`, T`Si $f$ est continue en $(0, 0)$, sa valeur le long de tout chemin qui mène à $(0, 0)$ tend vers $f(0, 0)$ : le passage est correct.` + H],
  [T`Or, pour $t \neq 0$, $f(t, t) = \dfrac{t^2}{2t^2} = \dfrac12$ : donc $\dfrac12 = 0$.`, T`Le calcul est exact, et une fonction constante a pour limite sa valeur : le passage est correct.` + H] ],
  T`Pour une fonction d'une variable, dérivable entraîne continue. Pour une fonction de deux variables, l'existence des dérivées partielles ne renseigne que sur le comportement le long des deux axes, et ne dit rien des autres directions : elle n'entraîne pas la continuité. Ce qui l'entraîne, c'est le caractère $\mathcal{C}^1$ : des dérivées partielles qui existent et sont continues au voisinage du point.`,
  T`Dérivées partielles en un point : information sur deux directions seulement. Classe $\mathcal{C}^1$ : entraîne la continuité et l'existence d'un développement limité à l'ordre 1.`, T`Que vaut $f$ sur la droite d'équation $y = x$ ?`),
faux('conditionnelles-somme', 'sup', Pr, 'ma-21', 'Deux conditionnelles de somme 1', T`On lance un dé équilibré. On note $A$ l'événement « obtenir 6 » et $B$ l'événement « obtenir un nombre pair ». « Démontrons » que $\dfrac13 = 1$.`, [
  [T`On a $P_B(A) = \dfrac13$ : parmi les trois résultats pairs, un seul est 6.`, T`C'est exact.`],
  [T`On a $P_{\overline B}(A) = 0$ : aucun résultat impair n'est 6.`, T`C'est exact.`],
  [T`Les événements $B$ et $\overline B$ sont contraires : donc $P_B(A) + P_{\overline B}(A) = 1$.`],
  [T`Ainsi $\dfrac13 + 0 = 1$, c'est-à-dire $\dfrac13 = 1$.`, T`On a remplacé chaque probabilité par sa valeur, calculée plus haut : le passage est correct.` + H] ],
  T`La formule vraie porte sur l'événement dont on calcule la probabilité, pas sur celui qui conditionne : $P_B(A) + P_B(\overline A) = 1$, parce que $P_B$ est une probabilité. Les nombres $P_B(A)$ et $P_{\overline B}(A)$ sont calculés avec deux probabilités différentes, et leur somme n'a pas de signification ; ce qui les relie, c'est la formule des probabilités totales, où chacun est pondéré.`,
  T`À $B$ fixé, $A \mapsto P_B(A)$ est une probabilité. À $A$ fixé, $B \mapsto P_B(A)$ n'en est pas une.`, T`Sur un arbre pondéré, quelles branches ont des probabilités de somme 1 ?`),
faux('anagrammes-repetees', 'sup', Pr, 'ma-21', 'Six anagrammes pour trois lettres', T`« Démontrons » que le mot ANA possède 6 anagrammes, alors qu'on n'en trouve que 3 : ANA, AAN et NAA.`, [
  [T`Une anagramme s'obtient en rangeant les lettres du mot dans un certain ordre.`, T`C'est la définition d'une anagramme.`],
  [T`Le mot ANA a 3 lettres.`, T`C'est exact : il y a trois lettres à placer.`],
  [T`Le nombre de façons de ranger 3 lettres est $3! = 6$ : le mot ANA a donc 6 anagrammes.`] ],
  T`Le nombre $3!$ compte les rangements de trois objets <em>distincts</em>. Ici les deux A sont indiscernables : en les échangeant, on obtient le même mot. Chaque anagramme est donc comptée $2!$ fois, et il y en a $\dfrac{3!}{2!} = 3$.`,
  T`Un mot de $n$ lettres où les lettres se répètent $m_1, \dots, m_k$ fois a $\dfrac{n!}{m_1! \cdots m_k!}$ anagrammes.`, T`Si l'on distingue les deux A en les notant A₁ et A₂, combien de rangements donnent le mot ANA ?`),
];
